import OpenAI from "openai"
const client = new OpenAI()
export async function routeTicket(text: string): Promise<"billing" | "bug" | "other"> {
  const res = await client.chat.completions.create({
    model: "gpt-4o",
    messages: [{ role: "user", content: `Classify this ticket as billing, bug or other. Reply with one word.\n\n${text}` }],
  })
  const label = res.choices[0]?.message.content?.trim().toLowerCase()
  return label === "billing" || label === "bug" ? label : "other"
}
